# Generated by manage.py generate_test_cases.
from django.contrib.auth import get_user_model
from django.http import HttpResponse

from bloomerp.communication.builtins.instant_messaging.controller import IMController
from bloomerp.models.communication.instant_messaging import IMConnection, IMConversation
from bloomerp.tests.base import (
    BloomerpComponentTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestStartConversationComponent(BloomerpComponentTestCase):
    """Verify authenticated creation and revalidation at the selection boundary."""

    view_name = "components_im_start_conversation"

    def select_recipient(self, scenario: RequestScenario) -> None:
        """Choose another active staff user from the standard fixtures."""
        scenario.data = {"recipient_id": str(self.normal_user.pk)}

    def existing_conversation(self, scenario: RequestScenario) -> None:
        """Create the same direct conversation before retrying selection."""
        self.select_recipient(scenario)
        IMController(self.admin_user).start_internal_conversation(
            str(self.normal_user.pk)
        )

    def select_staff_without_policies(self, scenario: RequestScenario) -> None:
        """Select another ordinary staff account with no user visibility grants."""
        recipient = get_user_model().objects.create(username="other_staff", is_staff=True)
        scenario.data = {"recipient_id": str(recipient.pk)}

    def select_non_staff(self, scenario: RequestScenario) -> None:
        """Attempt to start a conversation with a non-staff account."""
        recipient = get_user_model().objects.create(username="non_staff_recipient")
        scenario.data = {"recipient_id": str(recipient.pk)}

    def select_inactive_staff(self, scenario: RequestScenario) -> None:
        """Attempt to start a conversation with inactive staff."""
        recipient = get_user_model().objects.create(
            username="inactive_recipient", is_staff=True, is_active=False
        )
        scenario.data = {"recipient_id": str(recipient.pk)}

    def select_self(self, scenario: RequestScenario) -> None:
        """Attempt to start a direct conversation with the requester."""
        scenario.data = {"recipient_id": str(self.normal_user.pk)}

    def prepare_non_staff_actor(self, scenario: RequestScenario) -> None:
        """Select staff from a non-staff requester to verify sender eligibility."""
        scenario.user = get_user_model().objects.create(username="non_staff_actor")
        scenario.data = {"recipient_id": str(self.normal_user.pk)}

    def validate_native_conversation(self, response: HttpResponse) -> bool:
        """Confirm exactly one direct chat exists and no connection was provisioned."""
        return (
            IMConversation.objects.count() == 1
            and IMConversation.objects.filter(connection__isnull=True).count() == 1
            and not IMConnection.objects.exists()
            and "im:conversation-opened" in response.get("HX-Trigger", "")
        )

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Exercise creation, duplicate selection, denied access and request methods."""
        return [
            RequestScenario(
                name="Create native conversation",
                method="POST",
                user=self.admin_user,
                prepare=self.select_recipient,
                expected=ExpectedResult(
                    response_validators=[
                        self.validate_native_conversation,
                        self.contains_text("bloomerp-text-editor"),
                    ]
                ),
            ),
            RequestScenario(
                name="Reuse native direct conversation",
                method="POST",
                user=self.admin_user,
                prepare=self.existing_conversation,
                expected=ExpectedResult(
                    response_validators=[self.validate_native_conversation]
                ),
            ),
            RequestScenario(
                name="Staff without policies can message staff without policies",
                method="POST",
                user=self.normal_user,
                prepare=self.select_staff_without_policies,
                expected=ExpectedResult(
                    response_validators=[self.validate_native_conversation]
                ),
            ),
            RequestScenario(
                name="Reject non-staff recipient",
                method="POST",
                user=self.normal_user,
                prepare=self.select_non_staff,
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="Reject inactive staff recipient",
                method="POST",
                user=self.normal_user,
                prepare=self.select_inactive_staff,
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="Reject messaging self",
                method="POST",
                user=self.normal_user,
                prepare=self.select_self,
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="Reject non-staff requester",
                method="POST",
                prepare=self.prepare_non_staff_actor,
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="Reject malformed recipient",
                method="POST",
                user=self.admin_user,
                data={"recipient_id": "invalid"},
                expected=ExpectedResult(status_code=400),
            ),
            RequestScenario(
                name="GET cannot create",
                user=self.admin_user,
                expected=ExpectedResult(status_code=405),
            ),
            RequestScenario(
                name="Anonymous cannot create",
                method="POST",
                expected=ExpectedResult(status_code=302),
            ),
        ]
